type individual_status = {
  alien : alien_individual; (* underlying alien_individual data from 7701(b)(1)(A) *)
  is_us_citizen : bool; (* whether individual is a citizen of the United States *)
}

module Alien_status = struct
  (* 7701(b)(1)(A): resident alien test, reused from sub-provision *)
  let is_resident_alien_status (individual : individual_status) (year : int) : bool =
    is_resident_alien individual.alien year

  (* 7701(b)(1)(B): nonresident alien if neither a US citizen nor a resident alien *)
  let is_nonresident_alien (individual : individual_status) (year : int) : bool =
    not individual.is_us_citizen &&
    not (is_resident_alien_status individual year)
end
